const r = wb.getRange("'3 straights to 3 boxed'!G2:G16");
const st = r.getStyle();
st.setFillSolid('#EBF1DE');
st.setFont({ weight: 700 });
const s = wb.getWorksheet('3 straights to 3 boxed');
const res = [];
for (const a of ['G2','G8','G16']) { const c = wb.getRange(`'3 straights to 3 boxed'!${a}`); res.push([a, c.getCell().getValue(), c.getStyle().getFont().toJSON?.(), c.getStyle().getFill().toJSON?.(), c.getStyle().getNumberFormat()]); }
log(JSON.stringify(res));
log(s.getRegions('fill'));
log(s.getRegions('font'));
